function validateCareers(list){
  var errors = [];
  list.forEach(function(c){
    if(!c.keys || !c.keys.length) errors.push(c.id + ': missing buckets');
    (c.src||[]).forEach(function(pair){
      var s = (pair[0]||'') + ' ' + (pair[1]||'');
      if(CHANGELOG_SRC.test(s)) errors.push(c.id + ': changelog word in src');
    });
    var blob = JSON.stringify(c);
    if(EM_DASH.test(blob)) errors.push(c.id + ': em dash');
  });
  return errors;
}

